<?php
// Read-only list filters. Dispatch, cancellation and receiving retain their existing posting workflows.
function gmt_tabs(){return ['all'=>'All','to_ship'=>'To Ship','shipped'=>'Shipped','delivered'=>'Delivered / Completed','cancelled'=>'Cancelled','failed'=>'Failed Delivery','returns'=>'Return / Refund'];}
function gmt_status($o){$reported=oa_reported($o)['status'];return oa_deferred($reported)?$reported:$o['platform_status'];}
function gmt_bucket($o){return ['To Ship'=>'to_ship','Shipped'=>'shipped','Delivered'=>'delivered','Completed'=>'delivered','Cancelled'=>'cancelled','Failed Delivery'=>'failed','Return / Refund'=>'returns'][gmt_status($o)]??'other';}
function gmt_receipt($o){if($o['posting']!=='Posted')return '';if(($o['aftersales_resolution']??'')==='Refund Only')return 'none';$id=(int)$o['id'];if(isset($GLOBALS['GMT_RECEIPTS'][$id]))return $GLOBALS['GMT_RECEIPTS'][$id];$totals=om_existing_totals($id);if(!$totals)return '';$expected=$received=0;foreach($totals as $pid=>$qty){$expected+=$qty;$received+=min($qty,order_return_balance($o['platform'],$o['order_no'],$pid)['returned']);}return $GLOBALS['GMT_RECEIPTS'][$id]=$received>=$expected?'received':($received>0?'partial':'awaiting');}
function gmt_receipt_label($o){if(!oa_deferred(gmt_status($o))||$o['posting']!=='Posted')return '';return ['awaiting'=>'Awaiting Physical Return','partial'=>'Partially Received','received'=>'Fully Received','none'=>'No Physical Return / Refund Only'][gmt_receipt($o)]??'';}
function gmt_attention($o,$value){if($value===''||$value==='all')return true;$text=mb_strtolower((string)$o['exception_text']);$missing=$o['monitoring']==='Missing'||str_contains($text,'missing');$short=(bool)preg_match('/short|insufficient|negative|available stock/',$text);if(!$short&&in_array($value,['shortage','open'],true)&&$o['posting']==='Not Posted')foreach(om_query('SELECT product_id FROM om_reservations WHERE order_id=? AND qty>0',[$o['id']]) as $r)if(om_available($r['product_id'])<0||om_available($r['product_id'],$o['platform'])<0){$short=true;break;}$conflict=(bool)preg_match('/conflict|rollback|predates|validation|unknown|mismatch|not posted|needs checking/',$text)||$o['platform_status']==='Needs Checking';return match($value){'missing'=>$missing,'shortage'=>$short,'conflict'=>$conflict,'followup'=>in_array($o['monitoring'],['Needs Follow-up','Carried Over','Missing'],true)||oa_pending($o),'aging'=>oa_aging($o)['aging'],'cancellation'=>oc_pending_cancellation($o),'return_pending'=>oc_return_pending($o),'exceptions'=>(bool)$text||($o['posting']==='Not Posted'&&in_array($o['platform_status'],['Shipped','Delivered','Completed'],true)),'dispatch'=>in_array($o['platform_status'],['To Ship','Unpaid','Needs Checking'],true)&&$o['posting']!=='Reversed','delivery'=>$o['platform_status']==='Shipped'&&$o['posting']==='Posted','open'=>(bool)$text||$missing||$short||$conflict||oa_aging($o)['aging']||oc_pending_cancellation($o)||oc_return_pending($o),default=>false};}
function gmt_match($o,$input){$tab=$input['status_tab']??'all';if(!isset(gmt_tabs()[$tab]))$tab='all';if($tab!=='all'&&gmt_bucket($o)!==$tab)return false;if(!gmt_attention($o,$input['attention']??''))return false;if(in_array($tab,['failed','returns'],true)&&in_array($input['receipt']??'', ['awaiting','partial','received','none'],true)&&gmt_receipt($o)!==$input['receipt'])return false;return true;}
function gmt_input($input){if(gm_platform($input)==='Manual')return $input;$tabs=gmt_tabs();if(!isset($input['status_tab']))$input['status_tab']=['To Ship'=>'to_ship','Shipped'=>'shipped','Delivered'=>'delivered','Completed'=>'delivered','Cancelled'=>'cancelled','Failed Delivery'=>'failed','Return / Refund'=>'returns'][$input['platform_status']??'']??'all';if(!isset($tabs[$input['status_tab']]))$input['status_tab']='all';$view=$input['report_view']??'all';if(empty($input['attention']))$input['attention']=['dispatch'=>'dispatch','delivery'=>'delivery','cancellations'=>'cancellation','returns'=>'return_pending','exceptions'=>'exceptions','open'=>'followup'][$view]??'';if(empty($input['attention'])&&($input['monitoring']??'')==='Missing')$input['attention']='missing';if(empty($input['attention'])&&in_array($input['monitoring']??'',['Needs Follow-up','Carried Over'],true))$input['attention']='followup';unset($input['platform_status'],$input['monitoring'],$input['reported_status']);$input['report_view']='all';if(($input['reference_type']??'all')!=='advance')unset($input['booking_link']);if(!in_array($input['status_tab'],['failed','returns'],true))unset($input['receipt']);return $input;}
function gmt_badge($o){$s=gmt_status($o);if($s===$o['platform_status'])return oa_status_badge($o);$color=$s==='Cancelled'?'orange':'purple';return '<span class="oa-status oa-'.$color.'">'.e($s).'</span>';}
function gmt_filter_ui($input){$base=$input;unset($base['status_tab'],$base['receipt'],$base['om_offset'],$base['download'],$base['format']);$counts=array_fill_keys(array_keys(gmt_tabs()),0);foreach(gm_records($base) as $r){$counts['all']++;$bucket=gmt_bucket($r);if(isset($counts[$bucket]))$counts[$bucket]++;}echo '<nav class="gmt-status-tabs" aria-label="Order status">';foreach(gmt_tabs() as $key=>$label){$query=$base;$query['page']='order_monitor';$query['status_tab']=$key;echo '<a class="gmt-status-tab'.($input['status_tab']===$key?' active':'').'"'.($input['status_tab']===$key?' aria-current="page"':'').' href="?'.e(http_build_query($query)).'">'.'<span class="gmt-status-label">'.e($label).'</span><span class="gmt-status-count">'.number_format($counts[$key]).'</span></a>';}echo '</nav><div class="card"><form method="get" class="gmt-filter"><input type="hidden" name="page" value="order_monitor"><input type="hidden" name="platform" value="'.e($input['platform']).'"><input type="hidden" name="status_tab" value="'.e($input['status_tab']).'"><input type="hidden" name="more_filters" value="'.(!empty($input['more_filters'])?'1':'0').'"><div class="gm-filters gmt-primary"><label>Search<input name="q" placeholder="Booking / Order / Tracking / Product / SKU" value="'.e($input['q']??'').'"></label><label>From Date<input name="from" type="date" value="'.e($input['from']??'').'"></label><label>To Date<input name="to" type="date" value="'.e($input['to']??'').'"></label>';
 om_select('aging','Aging',[''=>'All Orders','only'=>'Aging Only','not'=>'Not Aging'],$input['aging']??'');om_select('sort','Sort By',['newest'=>'Latest fulfillment first','oldest'=>'Oldest fulfillment first','aging_oldest'=>'Longest status age first','aging_latest'=>'Shortest status age first'],$input['sort']??'newest');om_select('reference_type','Order Type',['all'=>'All Orders','regular'=>'Regular Orders','advance'=>'Advance Fulfillment'],$input['reference_type']??'all');echo '</div>';
 $active=(int)!empty($input['posting'])+(int)!empty($input['attention'])+(int)(($input['reference_type']??'all')==='advance'&&in_array($input['booking_link']??'all',['pending','linked'],true))+(int)!empty($input['receipt']);echo '<details class="gmt-more"'.($active||!empty($input['more_filters'])?' open':'').'><summary>More Filters'.($active?' <span class="gmt-filter-count">'.$active.'</span>':'').'</summary><div class="gm-filters gmt-extra">';om_select('posting','Inventory Posting',['Not Posted','Posted','Reversed'],$input['posting']??'',true);om_select('attention','Needs Attention',['open'=>'Any Issue / Aging','missing'=>'Missing Status Update','conflict'=>'Status Conflict / Needs Checking','shortage'=>'Stock Shortage','followup'=>'Needs Follow-up / Carried Over','aging'=>'Aging Orders','cancellation'=>'Pending Cancellation Confirmation','return_pending'=>'Pending Actual Return','exceptions'=>'Posting / Status Exceptions','dispatch'=>'Open for Dispatch','delivery'=>'Open for Delivery'],$input['attention']??'',true);echo '<div data-gmt-booking'.(($input['reference_type']??'all')==='advance'?'':' hidden').'>';om_select('booking_link','Booking Link',['all'=>'All Bookings','pending'=>'Awaiting Assigned Order ID','linked'=>'Order ID Linked'],$input['booking_link']??'all');echo '</div>';if(in_array($input['status_tab'],['failed','returns'],true))om_select('receipt','Return Receipt',['awaiting'=>'Awaiting Physical Return','partial'=>'Partially Received','received'=>'Fully Received','none'=>'No Physical Return / Refund Only'],$input['receipt']??'',true);echo '</div></details><div class="om-actions gm-right"><a class="btn ghost" href="?page=order_monitor&platform='.e($input['platform']).'&status_tab='.e($input['status_tab']).'">Clear Filters</a><button class="btn primary">Apply Filters</button></div></form></div><script src="assets/order_monitor_tabs.js?v=5.9.25" defer></script>';}
